example.source:
deepml motion 0.3
module corpus.deepml_motion.example_01251
policy deterministic
policy no_network
skeleton Rig01251 { joint Root parent none joint Hip parent Root joint Knee parent Hip joint Foot parent Knee }
blend_tree Locomotion01251 parameter speed { idle at 0 walk at 1 run at 3 }
mask LowerBody { include [Hip, Knee, Foot] }
ik FootIK01251 chain [Hip, Knee, Foot] target GroundTarget iterations 11
retarget SourceRig5 -> Rig01251 map { Hips: Hip LeftFoot: Foot }
state_machine Move01251 { Idle -> Walk when speed > 0.1 Walk -> Run when speed > 2.0 Run -> Idle when speed == 0 }
root_motion from Root axes [x,z]
verify motion_hash == "invalid-01251"

